import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CisoyQNf.js";var i=JSON.parse(`{"title":"Android EventLog 场景索引","description":"按系统排查场景整理常用 Android EventLog，帮助快速定位启动、Activity、ANR、输入和性能问题。","frontmatter":{"title":"Android EventLog 场景索引","description":"按系统排查场景整理常用 Android EventLog，帮助快速定位启动、Activity、ANR、输入和性能问题。","date":"2026-08-30T00:00:00.000Z","outline":"deep"},"headers":[],"relativePath":"blog/eventlog-scenarios.md","filePath":"blog/eventlog-scenarios.md","lastUpdated":1788103295000}`),a={name:`blog/eventlog-scenarios.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="android-eventlog-场景索引" tabindex="-1">Android EventLog 场景索引 <a class="header-anchor" href="#android-eventlog-场景索引" aria-label="Permalink to “Android EventLog 场景索引”">​</a></h1><p>本文面向日常 log 分析，按“正在排查的系统场景”整理常用 EventLog。它不是完整 tag 定义表；字段含义和源码触发流程请查阅 <a href="./eventlogref.html">eventlogref.md</a>。</p><p>EventLog 位于 <code>events</code> buffer，常用查看方式：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threadtime</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threadtime</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;am_proc_start|am_proc_bound|wm_create_activity&quot;</span></span></code></pre></div><p>Windows 环境可将 <code>grep</code> 替换为 <code>findstr</code>。</p><h2 id="_1-系统启动" tabindex="-1">1. 系统启动 <a class="header-anchor" href="#_1-系统启动" aria-label="Permalink to “1. 系统启动”">​</a></h2><p>用于判断 SystemServer、AMS、PMS、开机动画和屏幕是否按阶段推进：</p><table tabindex="0"><thead><tr><th>关注阶段</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>启动计时开始</td><td><code>boot_progress_start</code>（3000）</td></tr><tr><td>SystemServer 开始运行</td><td><code>boot_progress_system_run</code>（3010）、<code>system_server_start</code>（3011）</td></tr><tr><td>系统资源预加载</td><td><code>boot_progress_preload_start</code>（3020）、<code>boot_progress_preload_end</code>（3030）</td></tr><tr><td>AMS 就绪</td><td><code>boot_progress_ams_ready</code>（3040）</td></tr><tr><td>PMS 启动、扫描和就绪</td><td><code>boot_progress_pms_start</code>（3060）、<code>boot_progress_pms_system_scan_start</code>（3070）、<code>boot_progress_pms_data_scan_start</code>（3080）、<code>boot_progress_pms_scan_end</code>（3090）、<code>boot_progress_pms_ready</code>（3100）</td></tr><tr><td>亮屏和开机动画结束</td><td><code>boot_progress_enable_screen</code>（3050）、<code>wm_boot_animation_done</code>（31007）、<code>sf_stop_bootanim</code>（60110）</td></tr></tbody></table><p>排查启动卡顿时，先比较相邻阶段的时间戳；某个阶段有开始事件但没有结束/就绪事件，通常就是下一步的重点。</p><h2 id="_2-启动应用或-activity" tabindex="-1">2. 启动应用或 Activity <a class="header-anchor" href="#_2-启动应用或-activity" aria-label="Permalink to “2. 启动应用或 Activity”">​</a></h2><p>用于确认“进程是否启动、是否 attach、Activity 是否创建和显示”：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>AMS 请求创建进程</td><td><code>am_proc_start</code>（30014）</td></tr><tr><td>应用进程 attach 到 AMS</td><td><code>am_proc_bound</code>（30010）</td></tr><tr><td>创建 Task/Activity</td><td><code>wm_create_task</code>（30004）、<code>wm_create_activity</code>（30005）</td></tr><tr><td>Activity 启动耗时</td><td><code>wm_activity_launch_time</code>（30009）</td></tr><tr><td>Activity 恢复和前台切换</td><td><code>wm_resume_activity</code>（30007）、<code>wm_set_resumed_activity</code>（30043）、<code>wm_focused_root_task</code>（30044）</td></tr><tr><td>应用侧生命周期回调</td><td><code>wm_on_create_called</code>（30057）、<code>wm_on_start_called</code>（30059）、<code>wm_on_resume_called</code>（30022）</td></tr><tr><td>顶层 resumed 状态</td><td><code>wm_on_top_resumed_gained_called</code>（30064）、<code>wm_on_top_resumed_lost_called</code>（30065）</td></tr></tbody></table><p>常用判断：有 <code>am_proc_start</code> 没有 <code>am_proc_bound</code>，优先检查进程启动、Zygote 和 attach 超时；有 <code>am_proc_bound</code> 但没有后续 Activity 事件，再检查 <code>bindApplication</code>、应用初始化和任务调度。</p><h2 id="_3-activity-切换、返回和销毁" tabindex="-1">3. Activity 切换、返回和销毁 <a class="header-anchor" href="#_3-activity-切换、返回和销毁" aria-label="Permalink to “3. Activity 切换、返回和销毁”">​</a></h2><p>用于分析页面切换、返回、配置变化重建以及生命周期卡顿：</p><table tabindex="0"><thead><tr><th>场景</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>新 Intent 到达</td><td><code>wm_new_intent</code>（30003）</td></tr><tr><td>暂停页面</td><td><code>wm_pause_activity</code>（30013）、<code>wm_on_paused_called</code>（30021）</td></tr><tr><td>停止页面</td><td><code>wm_stop_activity</code>（30048）、<code>wm_on_stop_called</code>（30049）</td></tr><tr><td>完成/销毁页面</td><td><code>wm_finish_activity</code>（30001）、<code>wm_destroy_activity</code>（30018）、<code>wm_on_destroy_called</code>（30060）</td></tr><tr><td>暂停失败</td><td><code>wm_failed_to_pause</code>（30012）</td></tr><tr><td>配置变化重建</td><td><code>wm_relaunch_resume_activity</code>（30019）、<code>wm_relaunch_activity</code>（30020）</td></tr><tr><td>Activity Result</td><td><code>wm_on_activity_result_called</code>（30062）</td></tr></tbody></table><p>重点比较系统侧事件（<code>wm_*_activity</code>）与应用回调事件（<code>wm_on_*_called</code>）之间的时间差。</p><h2 id="_4-anr、崩溃和进程异常退出" tabindex="-1">4. ANR、崩溃和进程异常退出 <a class="header-anchor" href="#_4-anr、崩溃和进程异常退出" aria-label="Permalink to “4. ANR、崩溃和进程异常退出”">​</a></h2><p>用于判断应用无响应、异常退出、启动失败以及 AMS 是否主动清理进程：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>应用无响应</td><td><code>am_anr</code>（30008）</td></tr><tr><td>应用崩溃</td><td><code>am_crash</code>（30039）</td></tr><tr><td>AMS/系统严重异常记录</td><td><code>am_wtf</code>（30040）</td></tr><tr><td>进程死亡</td><td><code>am_proc_died</code>（30011）</td></tr><tr><td>进程启动或 attach 超时</td><td><code>am_process_start_timeout</code>（30037）</td></tr><tr><td>未知进程尝试 attach</td><td><code>am_drop_process</code>（30033）</td></tr><tr><td>进程被 AMS 杀死</td><td><code>am_kill</code>（30023）</td></tr><tr><td>进程崩溃次数过多</td><td><code>am_process_crashed_too_much</code>（30032）</td></tr><tr><td>进程标记为 bad/good</td><td><code>am_proc_bad</code>（30015）、<code>am_proc_good</code>（30016）</td></tr></tbody></table><p>推荐关联同一 PID 和进程名，并按时间顺序查看：<code>am_proc_start</code> → <code>am_proc_bound</code> → <code>am_anr</code>/<code>am_crash</code>/<code>am_proc_died</code>。</p><h2 id="_5-进程状态、内存和性能" tabindex="-1">5. 进程状态、内存和性能 <a class="header-anchor" href="#_5-进程状态、内存和性能" aria-label="Permalink to “5. 进程状态、内存和性能”">​</a></h2><p>用于分析后台限制、进程优先级、PSS、CPU、压缩和低内存回收：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>内存概况</td><td><code>am_meminfo</code>（30046）</td></tr><tr><td>单进程内存 PSS</td><td><code>am_pss</code>（30047）</td></tr><tr><td>CPU 采样</td><td><code>am_cpu</code>（30104）</td></tr><tr><td>进程状态或 OOM 调整</td><td><code>am_proc_state_changed</code>（30112）、<code>am_oom_adj_misc</code>（30113）</td></tr><tr><td>低内存通知</td><td><code>am_low_memory</code>（30017）</td></tr><tr><td>进程压缩/解压</td><td><code>am_compact</code>（30063）</td></tr><tr><td>进程冻结/解冻</td><td><code>am_freeze</code>（30068）、<code>am_unfreeze</code>（30069）</td></tr><tr><td>Watchdog 监控和重启</td><td><code>watchdog</code>、<code>watchdog_proc_pss</code>、<code>watchdog_soft_reset</code>、<code>watchdog_hard_reset</code>（2802-2805）</td></tr><tr><td>Watchdog 统计</td><td><code>watchdog_pss_stats</code>、<code>watchdog_proc_stats</code>、<code>watchdog_meminfo</code>、<code>watchdog_vmstat</code>（2806-2810）</td></tr><tr><td>杀进程诊断</td><td><code>killinfo</code>（10195355）</td></tr></tbody></table><h2 id="_6-用户启动、切换和解锁" tabindex="-1">6. 用户启动、切换和解锁 <a class="header-anchor" href="#_6-用户启动、切换和解锁" aria-label="Permalink to “6. 用户启动、切换和解锁”">​</a></h2><p>用于分析多用户启动、前后台切换、解锁和用户可见性：</p><table tabindex="0"><thead><tr><th>排查阶段</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>AMS 切换用户</td><td><code>am_switch_user</code>（30041）</td></tr><tr><td>用户状态变化</td><td><code>am_user_state_changed</code>（30051）</td></tr><tr><td>UserController 流程</td><td><code>uc_start_user_internal</code>（30076）、<code>uc_unlock_user</code>（30077）、<code>uc_finish_user_boot</code>（30078）、<code>uc_dispatch_user_switch</code>（30079）、<code>uc_continue_user_switch</code>（30080）、<code>uc_send_user_broadcast</code>（30081）</td></tr><tr><td>用户启动/切换/解锁</td><td><code>ssm_user_starting</code>（30082）、<code>ssm_user_switching</code>（30083）、<code>ssm_user_unlocking</code>（30084）、<code>ssm_user_unlocked</code>（30085）</td></tr><tr><td>用户停止</td><td><code>ssm_user_stopping</code>（30086）、<code>ssm_user_stopped</code>（30087）、<code>ssm_user_completed_event</code>（30088）</td></tr><tr><td>用户可见性</td><td><code>um_user_visibility_changed</code>（30091）</td></tr></tbody></table><p>遇到“用户已切换但桌面未出现”，可重点检查 <code>uc_*</code>、<code>ssm_*</code> 的完成事件，以及后续 Activity/Window 事件是否出现。</p><h2 id="_7-通知、systemui-和界面交互" tabindex="-1">7. 通知、SystemUI 和界面交互 <a class="header-anchor" href="#_7-通知、systemui-和界面交互" aria-label="Permalink to “7. 通知、SystemUI 和界面交互”">​</a></h2><p>用于分析通知入队、通知栏操作、SystemUI 交互和界面性能：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>通知入队/取消</td><td><code>notification_enqueue</code>（2750）、<code>notification_cancel</code>（2751）、<code>notification_cancel_all</code>（2752）</td></tr><tr><td>通知栏打开/关闭</td><td><code>notification_panel_revealed</code>（27500）、<code>notification_panel_hidden</code>（27501）</td></tr><tr><td>通知可见性和展开</td><td><code>notification_visibility_changed</code>（27510）、<code>notification_expansion</code>（27511）、<code>notification_visibility</code>（27531）</td></tr><tr><td>通知点击和 Action</td><td><code>notification_clicked</code>（27520）、<code>notification_action_clicked</code>（27521）</td></tr><tr><td>通知取消、提醒和聚合</td><td><code>notification_canceled</code>（27530）、<code>notification_alert</code>（27532）、<code>notification_autogrouped</code>（27533）、<code>notification_unautogrouped</code>（275534）</td></tr><tr><td>SystemUI 状态栏/面板</td><td><code>sysui_statusbar_touch</code>（36000）、<code>sysui_notificationpanel_touch</code>（36020）、<code>sysui_quickpanel_touch</code>（36030）、<code>sysui_latency</code>（36070）、<code>sysui_keyguard</code>（36080）</td></tr><tr><td>CUJ 性能</td><td><code>jank_cuj_events_begin_request</code>（37001）、<code>jank_cuj_events_end_request</code>（37002）、<code>jank_cuj_events_cancel_request</code>（37003）</td></tr></tbody></table><h2 id="_8-输入、输入法和绘制" tabindex="-1">8. 输入、输入法和绘制 <a class="header-anchor" href="#_8-输入、输入法和绘制" aria-label="Permalink to “8. 输入、输入法和绘制”">​</a></h2><p>用于分析触摸/焦点分发、IME 显示隐藏、输入法动画以及 View 绘制：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>输入窗口和交互</td><td><code>input_interaction</code>（62000）、<code>input_focus</code>（62001）、<code>input_cancel</code>（62003）</td></tr><tr><td>IME 显示/隐藏</td><td><code>imf_show_ime</code>（32001）、<code>imf_hide_ime</code>（32002）、<code>imf_force_reconnect_ime</code>（32000）</td></tr><tr><td>IME 动画</td><td><code>imf_ime_anim_start</code>（32006）、<code>imf_ime_anim_finish</code>（32007）、<code>imf_ime_anim_cancel</code>（32008）</td></tr><tr><td>IME 远程动画</td><td><code>imf_ime_remote_anim_start</code>（32009）、<code>imf_ime_remote_anim_end</code>（32010）、<code>imf_ime_remote_anim_cancel</code>（32011）</td></tr><tr><td>ViewRoot 绘制/布局</td><td><code>viewroot_draw</code>（60000）、<code>viewroot_layout</code>（60001）、<code>viewroot_draw_event</code>（60004）</td></tr><tr><td>SurfaceView</td><td><code>surfaceview_layout</code>（60005）、<code>surfaceview_callback</code>（60006）</td></tr></tbody></table><h2 id="_9-网络、wi-fi-和蜂窝数据" tabindex="-1">9. 网络、Wi-Fi 和蜂窝数据 <a class="header-anchor" href="#_9-网络、wi-fi-和蜂窝数据" aria-label="Permalink to “9. 网络、Wi-Fi 和蜂窝数据”">​</a></h2><p>用于分析网络连接、Wi-Fi 状态、VPN、NTP 校时以及蜂窝数据建立失败：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>网络连接状态</td><td><code>connectivity_state_changed</code>（50020）</td></tr><tr><td>Wi-Fi 总体状态</td><td><code>wifi_state_changed</code>（50021）</td></tr><tr><td>Wi-Fi 事件和 supplicant</td><td><code>wifi_event_handled</code>（50022）、<code>wifi_supplicant_state_changed</code>（50023）</td></tr><tr><td>NTP 校时</td><td><code>ntp_success</code>（50080）、<code>ntp_failure</code>（50081）</td></tr><tr><td>移动/Wi-Fi 流量采样</td><td><code>netstats_mobile_sample</code>（51100）、<code>netstats_wifi_sample</code>（51101）</td></tr><tr><td>VPN Lockdown</td><td><code>lockdown_vpn_connecting</code>（51200）、<code>lockdown_vpn_connected</code>（51201）、<code>lockdown_vpn_error</code>（51202）</td></tr><tr><td>PDP 数据连接</td><td><code>pdp_bad_dns_address</code>（50100）、<code>pdp_setup_fail</code>（50105）、<code>pdp_network_drop</code>（50109）</td></tr><tr><td>GSM/CDMA 状态</td><td><code>gsm_data_state_change</code>（50113）、<code>gsm_service_state_change</code>（50114）、<code>cdma_data_state_change</code>（50115）、<code>cdma_service_state_change</code>（50116）</td></tr><tr><td>数据恢复</td><td><code>data_stall_recovery_get_data_call_list</code>（50118）、<code>data_stall_recovery_cleanup</code>（50119）、<code>data_stall_recovery_reregister</code>（50120）、<code>data_stall_recovery_radio_restart</code>（50121）</td></tr></tbody></table><h2 id="_10-电源、电池、温度和存储" tabindex="-1">10. 电源、电池、温度和存储 <a class="header-anchor" href="#_10-电源、电池、温度和存储" aria-label="Permalink to “10. 电源、电池、温度和存储”">​</a></h2><p>用于分析耗电、亮灭屏、唤醒锁、电池状态、温度和磁盘空间：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>电池电量和状态</td><td><code>battery_level</code>（2722）、<code>battery_status</code>（2723）、<code>battery_discharge</code>（2730）</td></tr><tr><td>电池省电模式</td><td><code>battery_saver_mode</code>（2739）、<code>battery_saving_stats</code>（27390）、<code>battery_saver_setting</code>（27392）</td></tr><tr><td>睡眠和唤醒</td><td><code>power_sleep_requested</code>（2724）、<code>power_partial_wake_state</code>（2729）、<code>power_soft_sleep_requested</code>（2731）</td></tr><tr><td>屏幕状态</td><td><code>power_screen_broadcast_send</code>（2725）、<code>power_screen_broadcast_done</code>（2726）、<code>power_screen_broadcast_stop</code>（2727）、<code>power_screen_state</code>（2728）</td></tr><tr><td>温度</td><td><code>thermal_changed</code>（2737）</td></tr><tr><td>存储状态</td><td><code>storage_state</code>（2749）</td></tr><tr><td>磁盘/eMMC 统计</td><td><code>storaged_disk_stats</code>（2732）、<code>storaged_emmc_info</code>（2733）</td></tr><tr><td>文件系统整理</td><td><code>fstrim_start</code>（2755）、<code>fstrim_finish</code>（2756）</td></tr></tbody></table><h2 id="_11-包管理、安装和数据清理" tabindex="-1">11. 包管理、安装和数据清理 <a class="header-anchor" href="#_11-包管理、安装和数据清理" aria-label="Permalink to “11. 包管理、安装和数据清理”">​</a></h2><p>用于分析安装配置失败、清理应用数据和 PackageManager 关键状态：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>PackageManager 关键诊断</td><td><code>pm_critical_info</code>（3120）</td></tr><tr><td>包管理统计/快照</td><td><code>pm_package_stats</code>（3121）、<code>pm_snapshot_stats</code>（3130）、<code>pm_snapshot_rebuild</code>（3131）</td></tr><tr><td>清理应用数据</td><td><code>pm_clear_app_data_caller</code>（3132）、<code>installer_clear_app_data_caller</code>（39000）、<code>installer_clear_app_data_call_stack</code>（39001）</td></tr><tr><td>配置安装失败</td><td><code>config_install_failed</code>（51300）</td></tr><tr><td>未知来源开关</td><td><code>unknown_sources_enabled</code>（3110）</td></tr></tbody></table><h2 id="_12-备份和恢复" tabindex="-1">12. 备份和恢复 <a class="header-anchor" href="#_12-备份和恢复" aria-label="Permalink to “12. 备份和恢复”">​</a></h2><p>用于分析 Key-Value/Full Backup、Transport、Agent 和配额问题：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>Backup 数据变化和启动</td><td><code>backup_data_changed</code>（2820）、<code>backup_start</code>（2821）、<code>backup_requested</code>（2828）</td></tr><tr><td>Backup Transport/Agent</td><td><code>backup_transport_failure</code>（2822）、<code>backup_agent_failure</code>（2823）、<code>backup_transport_lifecycle</code>（2850）、<code>backup_transport_connection</code>（2851）</td></tr><tr><td>Backup 包和结果</td><td><code>backup_package</code>（2824）、<code>backup_success</code>（2825）、<code>backup_quota_exceeded</code>（2829）</td></tr><tr><td>Restore 流程</td><td><code>restore_start</code>（2830）、<code>restore_transport_failure</code>（2831）、<code>restore_agent_failure</code>（2832）、<code>restore_package</code>（2833）、<code>restore_success</code>（2834）</td></tr><tr><td>Full Backup/Restore</td><td><code>full_backup_package</code>（2840）、<code>full_backup_agent_failure</code>（2841）、<code>full_backup_transport_failure</code>（2842）、<code>full_backup_success</code>（2843）、<code>full_restore_package</code>（2844）、<code>full_backup_cancelled</code>（2846）</td></tr></tbody></table><h2 id="_13-安全审计和-selinux" tabindex="-1">13. 安全审计和 SELinux <a class="header-anchor" href="#_13-安全审计和-selinux" aria-label="Permalink to “13. 安全审计和 SELinux”">​</a></h2><p>用于分析 SELinux AVC、设备策略、安全日志和实验性安全检测：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag）</th></tr></thead><tbody><tr><td>SELinux/内核审计</td><td><code>auditd</code>（1003）</td></tr><tr><td>ADB 和安全日志开关</td><td><code>security_adb_shell_interactive</code>（210001）、<code>security_adb_shell_command</code>（210002）、<code>security_logging_started</code>（210011）、<code>security_logging_stopped</code>（210012）</td></tr><tr><td>Keyguard/设备策略</td><td><code>security_keyguard_dismissed</code>（210006）、<code>security_keyguard_secured</code>（210008）、<code>security_remote_lock</code>（210022）、<code>security_wipe_failed</code>（210023）</td></tr><tr><td>密钥/证书</td><td><code>security_key_generated</code>（210024）、<code>security_key_imported</code>（210025）、<code>security_key_destroyed</code>（210026）、<code>security_cert_authority_installed</code>（210029）、<code>security_cert_authority_removed</code>（210030）</td></tr><tr><td>网络/媒体/包安全事件</td><td><code>security_wifi_connection</code>（210037）、<code>security_wifi_disconnection</code>（210038）、<code>security_media_mounted</code>（210013）、<code>security_media_unmounted</code>（210014）、<code>security_package_installed</code>（210041）、<code>security_package_uninstalled</code>（210043）</td></tr><tr><td>SafetyNet/Snet</td><td><code>snet</code>（206001）、<code>snet_event_log</code>（1397638484）</td></tr></tbody></table><h2 id="_14-automotive-车载系统" tabindex="-1">14. Automotive 车载系统 <a class="header-anchor" href="#_14-automotive-车载系统" aria-label="Permalink to “14. Automotive 车载系统”">​</a></h2><p>用于分析 Car Service 启动、VHAL、用户生命周期和车载电源策略：</p><table tabindex="0"><thead><tr><th>排查问题</th><th>EventLog（tag 范围）</th></tr></thead><tbody><tr><td>Car Service Helper</td><td><code>car_helper_*</code>（150000-150016）</td></tr><tr><td>Car Service 生命周期/VHAL</td><td><code>car_service_*</code>（150050-150060）</td></tr><tr><td>CarUserService 用户流程</td><td><code>car_user_svc_*</code>、<code>car_initial_user_*</code>、<code>car_user_hal_*</code>（150100-150155）</td></tr><tr><td>CarUserManager 客户端调用</td><td><code>car_user_mgr_*</code>（150171-150191）</td></tr><tr><td>用户数据管理</td><td><code>car_dp_mgr_*</code>（150200-150207）</td></tr><tr><td>车载电源管理</td><td><code>car_pwr_mgr_*</code>（150300-150303）</td></tr><tr><td>Car Watchdog</td><td><code>car_watchdog_svc_io_overuse_kill</code>（150400）</td></tr></tbody></table><p>车载事件的完整字段和具体类方法请直接在 <a href="./eventlogref.html">eventlogref.md</a> 中搜索事件名，或到 <code>packages/services/Car</code> 搜索 <code>EventLogTags.write...</code>。</p><h2 id="_15-快速选择规则" tabindex="-1">15. 快速选择规则 <a class="header-anchor" href="#_15-快速选择规则" aria-label="Permalink to “15. 快速选择规则”">​</a></h2><p>遇到问题时可以先按下面的最小集合过滤：</p><table tabindex="0"><thead><tr><th>问题</th><th>第一组关键词</th></tr></thead><tbody><tr><td>开机慢/卡开机</td><td><code>boot_progress_</code>、<code>system_server_start</code>、<code>wm_boot_animation_done</code>、<code>sf_stop_bootanim</code></td></tr><tr><td>冷启动慢</td><td><code>am_proc_start</code>、<code>am_proc_bound</code>、<code>wm_create_activity</code>、<code>wm_activity_launch_time</code></td></tr><tr><td>Activity 切换异常</td><td><code>wm_pause_activity</code>、<code>wm_resume_activity</code>、<code>wm_relaunch_activity</code>、<code>wm_finish_activity</code></td></tr><tr><td>应用 ANR/崩溃</td><td><code>am_anr</code>、<code>am_crash</code>、<code>am_proc_died</code>、<code>am_kill</code></td></tr><tr><td>内存压力</td><td><code>am_meminfo</code>、<code>am_pss</code>、<code>am_low_memory</code>、<code>watchdog_</code>、<code>killinfo</code></td></tr><tr><td>用户切换/解锁</td><td><code>am_switch_user</code>、<code>uc_</code>、<code>ssm_</code>、<code>um_user_visibility_changed</code></td></tr><tr><td>通知不显示/点击异常</td><td><code>notification_</code>、<code>sysui_</code>、<code>jank_cuj_events_</code></td></tr><tr><td>输入法/触摸异常</td><td><code>input_</code>、<code>imf_</code>、<code>viewroot_</code></td></tr><tr><td>无网/Wi-Fi/移动数据</td><td><code>connectivity_</code>、<code>wifi_</code>、<code>pdp_</code>、<code>gsm_</code>、<code>cdma_</code>、<code>data_</code></td></tr><tr><td>耗电/亮灭屏异常</td><td><code>battery_</code>、<code>power_</code>、<code>thermal_changed</code>、<code>storage_state</code></td></tr></tbody></table>`,56)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};